// Add / edit product with the size x colour grid (REQ-PRD-1/2/3). One save creates every variant,
// with SKU and EAN-13 barcode generated by the server, and records opening stock.
const $ = id => document.getElementById(id);
const id = param('id');
let product = null;
let canEdit = false;
const variants = new Map();   // "size|colour" -> variant row

const split = s => [...new Set(s.split(',').map(x => x.trim()).filter(Boolean))];
const key = (s, c) => s.toLowerCase() + '|' + c.toLowerCase();

requireLogin().then(async me => {
  canEdit = me.role === 'OWNER';
  const cats = await api('/categories');
  $('categoryId').innerHTML = '<option value="">Choose…</option>' + cats.filter(c => c.parent_id || !cats.some(x => x.parent_id === c.category_id))
    .map(c => `<option value="${c.category_id}" data-name="${esc(c.name)}">${esc(c.label)}</option>`).join('');

  if (id) {
    product = await api('/products/' + id);
    fill(product);
    $('shareBtn').classList.remove('hidden');
    $('shareBtn').onclick = () => openShare(product.id);
  }
  if (!canEdit) {
    $('ro').classList.remove('hidden');
    document.querySelectorAll('.edit-only, .cost-col').forEach(e => e.classList.add('hidden'));
    document.querySelectorAll('main input, main select').forEach(e => e.disabled = true);
  }
  $('sizes').addEventListener('input', debounce(rebuild, 300));
  $('colours').addEventListener('input', debounce(rebuild, 300));
  $('categoryId').onchange = suggestTaxClass;
  $('hsnCode').addEventListener('input', suggestTaxClass);
  $('applyDefaults').onclick = applyDefaults;
  $('clearance').onchange = () => $('clearanceReason').classList.toggle('hidden', !$('clearance').checked);
  $('save').onclick = save;
  rebuild();
});

function fill(p) {
  $('title').textContent = p.name;
  document.title = p.name + ' – Mansi Collection';
  $('name').value = p.name;
  $('categoryId').value = p.categoryId;
  $('brand').value = p.brand || '';
  $('fabric').value = p.fabric || '';
  $('gender').value = p.gender;
  $('hsnCode').value = p.hsnCode;
  $('taxClass').value = p.taxClass;
  $('returnable').checked = p.returnable;
  $('active').checked = p.active;
  p.variants.forEach(v => variants.set(key(v.size, v.colour), { ...v }));
  $('sizes').value = [...new Set(p.variants.map(v => v.size))].join(', ');
  $('colours').value = [...new Set(p.variants.map(v => v.colour))].join(', ');
  const first = p.variants[0];
  if (first) {
    $('dCost').value = first.costPrice ?? '';
    $('dSell').value = first.sellingPrice;
    $('dMrp').value = first.mrp;
  }
}

function suggestTaxClass() {
  const opt = $('categoryId').selectedOptions[0];
  const cat = opt ? (opt.dataset.name || '') : '';
  const hsn = $('hsnCode').value;
  const fabric = /saree/i.test(cat) || /unstitched/i.test($('name').value) || /^5[0-5]/.test(hsn);
  $('taxHint').textContent = fabric ? 'Looks like fabric (saree / suit length / HSN 50–55) → FABRIC, 5% at any price.' : '';
  if (fabric && !product) $('taxClass').value = 'FABRIC';
}

function defaults() {
  return {
    costPrice: $('dCost').value, sellingPrice: $('dSell').value, mrp: $('dMrp').value || $('dSell').value,
    reorderLevel: $('dReorder').value || 2,
  };
}

function rebuild() {
  const sizes = split($('sizes').value), colours = split($('colours').value);
  const d = defaults();
  for (const s of sizes) for (const c of colours) {
    if (!variants.has(key(s, c))) variants.set(key(s, c), { id: null, size: s, colour: c, openingStock: 0, barcode: '', ...d });
  }
  // Drop new (unsaved) combos that are no longer in the lists; saved variants always stay.
  const sl = sizes.map(x => x.toLowerCase()), cl = colours.map(x => x.toLowerCase());
  for (const [k, v] of variants) {
    if (!v.id && !(sl.includes(v.size.toLowerCase()) && cl.includes(v.colour.toLowerCase()))) variants.delete(k);
  }
  drawGrid(sizes, colours);
  drawTable();
}

function applyDefaults() {
  const d = defaults();
  for (const v of variants.values()) if (!v.id) Object.assign(v, d);
  drawTable();
}

function drawGrid(sizes, colours) {
  if (!sizes.length || !colours.length) {
    $('vgrid').innerHTML = '<tr><td class="muted">Enter sizes and colours above to build the grid.</td></tr>';
    return;
  }
  $('vgrid').innerHTML = `<thead><tr><th>Colour \\ Size</th>${sizes.map(s => `<th>${esc(s)}</th>`).join('')}</tr></thead><tbody>` +
    colours.map(c => `<tr><td><b>${esc(c)}</b></td>${sizes.map(s => {
      const v = variants.get(key(s, c));
      if (!v) return '<td></td>';
      if (v.id) return `<td>${stockBadge(v)}</td>`;
      return `<td><input type="number" min="0" max="99999" data-open="${esc(key(s, c))}" value="${v.openingStock || ''}" placeholder="0"></td>`;
    }).join('')}</tr>`).join('') + '</tbody>';
  $('vgrid').querySelectorAll('[data-open]').forEach(i => i.oninput = () => {
    variants.get(i.dataset.open).openingStock = Number(i.value || 0);
    drawTable();
  });
  if (!canEdit) $('vgrid').querySelectorAll('input').forEach(e => e.disabled = true);
}

function drawTable() {
  const rows = [...variants.values()];
  $('vbody').innerHTML = rows.map(v => {
    const k = esc(key(v.size, v.colour));
    const inp = (f, w = 100) => `<input type="number" data-k="${k}" data-f="${f}" value="${v[f] ?? ''}" min="0" step="1" style="width:${w}px;text-align:right">`;
    return `<tr><td>${esc(v.size)}</td><td>${esc(v.colour)}</td>
      <td class="small">${v.id ? esc(v.sku) : '<span class="badge info">new – auto</span>'}</td>
      <td class="small">${v.id ? esc(v.barcode) : `<input type="text" data-k="${k}" data-f="barcode" value="${esc(v.barcode || '')}" placeholder="auto" style="width:140px">`}</td>
      <td class="num cost-col">${inp('costPrice')}</td><td class="num">${inp('sellingPrice')}</td><td class="num">${inp('mrp')}</td>
      <td class="num">${inp('reorderLevel', 70)}</td><td class="num">${v.id ? v.stockQty : (v.openingStock || 0) + ' <span class="muted small">opening</span>'}</td></tr>`;
  }).join('') || '<tr><td colspan="9" class="muted">No variants yet</td></tr>';
  $('vbody').querySelectorAll('[data-k]').forEach(i => i.oninput = () => { variants.get(i.dataset.k)[i.dataset.f] = i.value; });
  if (!canEdit) {
    $('vbody').querySelectorAll('input').forEach(e => e.disabled = true);
    document.querySelectorAll('.cost-col').forEach(e => e.classList.add('hidden'));
  }
}

async function save() {
  document.querySelectorAll('.invalid').forEach(e => e.classList.remove('invalid'));
  clearMsg($('err'));
  const body = {
    name: $('name').value, categoryId: Number($('categoryId').value) || null, brand: $('brand').value,
    fabric: $('fabric').value, gender: $('gender').value, hsnCode: $('hsnCode').value.trim(),
    taxClass: $('taxClass').value, returnable: $('returnable').checked, active: $('active').checked,
    clearanceReason: $('clearance').checked ? $('clearanceReason').value : null,
    variants: [...variants.values()].map(v => ({
      id: v.id, size: v.size, colour: v.colour, costPrice: v.costPrice === '' ? null : Number(v.costPrice),
      sellingPrice: v.sellingPrice === '' ? null : Number(v.sellingPrice), mrp: v.mrp === '' ? null : Number(v.mrp),
      openingStock: v.id ? null : Number(v.openingStock || 0), reorderLevel: Number(v.reorderLevel || 0),
      barcode: v.id ? null : (v.barcode || null),
    })),
  };
  const btn = $('save');
  btn.disabled = true;
  try {
    const saved = await api(id ? '/products/' + id : '/products', { method: id ? 'PUT' : 'POST', body });
    toast(`Saved – ${saved.variants.length} variants`, 'ok');
    location.href = 'product-edit.html?id=' + saved.id;
  } catch (err) {
    showError($('err'), err);
    const f = err.field && document.getElementById(err.field.replace(/\[.*$/, ''));
    if (f) { f.classList.add('invalid'); f.focus(); }
    $('err').scrollIntoView({ behavior: 'smooth', block: 'center' });
  } finally {
    btn.disabled = false;
  }
}
